approved_command_preview:
$ErrorActionPreference = 'Stop'
$repo = $env:GITHUB_WORKSPACE
$requestedSha = '1784b6fe8db2d081b45eb1c471b50c2b7f1b95b3'
$worktree = Join-Path $env:RUNNER_TEMP 'dcoir-pr467-exact-head'
$outRoot = $env:DCOIR_DOWNLOADS_DIR
if ([string]::IsNullOrWhiteSpace($outRoot)) { $outRoot = Join-Path $env:RUNNER_TEMP 'dcoir-downloads' }
$outDir = Join-Path $outRoot 'pr467-exact-head-validation-modular-v42'
New-Item -ItemType Directory -Force -Path $outDir | Out-Null
if (Test-Path $worktree) { Remove-Item -Recurse -Force $worktree }
git -C $repo fetch --no-tags origin $requestedSha
if ($LASTEXITCODE -ne 0) { throw "git fetch failed for $requestedSha" }
git -C $repo worktree prune
git -C $repo worktree add --detach $worktree $requestedSha
if ($LASTEXITCODE -ne 0) { throw "git worktree add failed for $requestedSha" }
$validationFailed = $false
try {
  Set-Location $worktree
  $actualSha = (git rev-parse HEAD).Trim()
  if ($actualSha -ne $requestedSha) { throw "exact-head mismatch: requested=$requestedSha actual=$actualSha" }
  foreach ($name in @('OPENROUTER_API_KEY','DCOIR_OPENROUTER_API_KEY','OPENAI_API_KEY','DCOIR_OPENAI_API_KEY','DCOIR_GEMINI_API')) { Remove-Item "Env:$name" -ErrorAction SilentlyContinue }
  $configPath = Join-Path $worktree '.github/dcoir_review/openrouter-pr-review-pareto.yml'
  $validationCommands = New-Object System.Collections.Generic.List[string]
  $inValidation = $false
  foreach ($line in Get-Content -LiteralPath $configPath -Encoding UTF8) {
    if ($line -match '^validation_commands:\s*$') { $inValidation = $true; continue }
    if (-not $inValidation) { continue }
    if ($line -match '^[^\s#].*:\s*$') { break }
    if ($line -match '^\s{2}-\s+(.+)$') { $validationCommands.Add($Matches[1].Trim()) }
  }
  if ($validationCommands.Count -ne 36) { throw "expected 36 governed validation commands, found $($validationCommands.Count)" }
  function Invoke-DcoirValidationCommand {
    param([string]$Label,[string]$Command,[int]$Index)
    $safeLabel = ($Label -replace '[^A-Za-z0-9_.-]','_')
    $logPath = Join-Path $outDir ("{0:D2}-{1}.log" -f $Index,$safeLabel)
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $global:LASTEXITCODE = 0
    $captured = @()
    try {
      $captured = @(Invoke-Expression $Command 2>&1 | ForEach-Object { $_.ToString() })
      $exitCode = [int]$LASTEXITCODE
    } catch {
      $captured += $_.Exception.ToString()
      $exitCode = 1
    }
    $sw.Stop()
    @(("COMMAND: {0}" -f $Command),("EXIT_CODE: {0}" -f $exitCode),("DURATION_SECONDS: {0:N3}" -f $sw.Elapsed.TotalSeconds),'') + $captured | Set-Content -LiteralPath $logPath -Encoding UTF8
    [pscustomobject]@{ label=$Label; command=$Command; exit_code=$exitCode; duration_seconds=[math]::Round($sw.Elapsed.TotalSeconds,3); log_file=(Split-Path -Leaf $logPath) }
  }
  $results = New-Object System.Collections.Generic.List[object]
  $preflightCommand = 'python3 .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v42_selftest.py'
  $results.Add((Invoke-DcoirValidationCommand -Label 'preflight-v42' -Command $preflightCommand -Index 0))
  for ($i = 0; $i -lt $validationCommands.Count; $i++) {
    $results.Add((Invoke-DcoirValidationCommand -Label ("validation-{0:D2}" -f ($i + 1)) -Command $validationCommands[$i] -Index ($i + 1)))
  }
  $dirty = @(git status --porcelain)
  $failures = @($results | Where-Object { $_.exit_code -ne 0 })
  $receipt = [ordered]@{
    schema = 'dcoir.pr_exact_head_validation.v1'
    pr_number = 467
    requested_sha = $requestedSha
    actual_sha = $actualSha
    validation_command_count = $validationCommands.Count
    total_executions = $results.Count
    preflight_v42_passed = ($results[0].exit_code -eq 0)
    passed_count = @($results | Where-Object { $_.exit_code -eq 0 }).Count
    failed_count = $failures.Count
    worktree_dirty = ($dirty.Count -gt 0)
    dirty_paths = $dirty
    inference_credentials_removed = @('OPENROUTER_API_KEY','DCOIR_OPENROUTER_API_KEY','OPENAI_API_KEY','DCOIR_OPENAI_API_KEY','DCOIR_GEMINI_API')
    results = $results
  }
  $receipt | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $outDir 'validation_receipt.json') -Encoding UTF8
  @('# PR #467 exact-head deterministic validation','',"Requested SHA: $requestedSha","Actual SHA: $actualSha","Configured validation commands: $($validationCommands.Count)","Total executions: $($results.Count)","Passed: $($receipt.passed_count)","Failed: $($receipt.failed_count)","Worktree dirty after validation: $($receipt.worktree_dirty)") | Set-Content -LiteralPath (Join-Path $outDir 'summary.md') -Encoding UTF8
  if ($failures.Count -gt 0) { $validationFailed = $true }
} finally {
  Set-Location $repo
  if (Test-Path $worktree) { git -C $repo worktree remove --force $worktree | Out-Null }
  git -C $repo worktree prune
}
if ($validationFailed) { throw 'PR #467 exact-head deterministic validation failed; inspect validation_receipt.json and command logs.' }

